def solve():
    try:
        input_data = sys.stdin.read().strip()
        if not input_data:
            return
        n = int(input_data)
    except ValueError:
        return

    s = str(n)
    length = len(s)
    ans = 0

    # Count full blocks of odd lengths strictly less than the current length
    for l in range(1, length, 2):
        if l == 1:
            ans += 9
        else:
            ans += 9 * (10 ** (l - 1))

    # Count numbers with the same length as N that have odd digits
    # These are from 10^(length-1) to n
    start = 10 ** (length - 1)
    if length % 2 == 1:
        ans += (n - start + 1)

    print(ans)

if __name__ == "__main__":
    solve()

